from typing import Final

import pytest

DEFAULTS: Final[dict[str, str]] = {"mode": "fast", "level": "3"}


def settings(keys: list[str], values: list[str]) -> list[str]:
    """Overlay keys[i] -> values[i] on DEFAULTS and return the resulting values.

    Output order is mode, level, then any other keys in the order given.
    Raises ValueError if keys and values differ in length.
    """
    if len(keys) != len(values):
        raise ValueError("keys and values must have the same length")

    overlay: dict[str, str] = dict(DEFAULTS)
    for k, v in zip(keys, values, strict=True):
        overlay[k] = v

    extras: list[str] = [k for k in dict.fromkeys(keys) if k not in DEFAULTS]
    order: list[str] = ["mode", "level", *extras]
    return [overlay[k] for k in order]


def test_no_overrides_returns_defaults() -> None:
    assert settings([], []) == ["fast", "3"]


def test_override_mode() -> None:
    assert settings(["mode"], ["slow"]) == ["slow", "3"]


def test_override_level() -> None:
    assert settings(["level"], ["5"]) == ["fast", "5"]


def test_override_both_defaults() -> None:
    assert settings(["level", "mode"], ["5", "safe"]) == ["safe", "5"]


def test_extra_keys_follow_defaults_in_given_order() -> None:
    assert settings(["zeta", "alpha"], ["1", "2"]) == ["fast", "3", "1", "2"]


def test_extra_key_mixed_with_default_override() -> None:
    assert settings(["color", "level"], ["red", "9"]) == ["fast", "9", "red"]


def test_length_mismatch_raises() -> None:
    with pytest.raises(ValueError):
        settings(["mode"], [])
